#!/usr/bin/env bash
# ═══════════════════════════════════════════════════════════════════════════
# persist-appearance.sh — animations/input overrides generated by the panel.
#
# Port of persist-hypr.sh. The CLI matches shell persist-hypr.sh (including the
# workspace animation options) and the settings.json keys are unchanged; only
# the destination/format is compositor-neutral:
#
#   Hyprland: writes Lua modules in ~/.config/hypr/config/ (loaded at the end
#             of the Lua config, so they always win) and runs `hyprctl reload`.
#   niri:     writes KDL includes in ~/.config/niri/generated/ and reloads
#             with `niri msg action load-config-file`.
#
# Usage:
#   persist-appearance.sh animations <enabled 0|1> <speed_multiplier> <workspace_style> <curve> <special_style> <wrap 0|1> <window_open> <window_close>
#   persist-appearance.sh input <sensitivity> <accel_profile> <tap 0|1> <natural 0|1> <dwt 0|1>
#
# Animation options: style/special_style/wrap have no niri equivalent; they are
# parsed and validated (same contract as persist-hypr.sh) but ignored on niri.
# The niri writer emits enabled, the speed-scaled durations, the
# workspace-switch curve and the niri-only window-open/window-close presets
# (window_open/window_close; Hyprland ignores the two extra arguments).
#
# Environment:
#   HYPR_CONFIG_DIR    Hyprland output dir (default ~/.config/hypr/config)
#   NIRI_GENERATED_DIR niri output dir   (default ~/.config/niri/generated)
#   HYPR_NO_RELOAD=1   skip `hyprctl reload` (tests)
#   NIRI_NO_RELOAD=1   skip `niri msg action load-config-file` (tests)
#
# Merge note (Hyprland): hl.config merges partial tables, so user-input.lua
# omits kb_layout/kb_options/follow_mouse (kept in settings.lua). Under niri
# the generated `input {}` include is expected to be the only input source in
# the niri config tree; see docs/overlay.md.
# ═══════════════════════════════════════════════════════════════════════════

set -u

desktop="$(printf '%s' "${XDG_CURRENT_DESKTOP:-}" | tr '[:upper:]' '[:lower:]')"
case "$desktop" in
    *niri*) NIRI=1 ;;
    *)      [[ -n "${NIRI_SOCKET:-}" ]] && NIRI=1 || NIRI=0 ;;
esac

if [[ "$NIRI" == "1" ]]; then
    OUT_DIR="${NIRI_GENERATED_DIR:-$HOME/.config/niri/generated}"
else
    OUT_DIR="${HYPR_CONFIG_DIR:-$HOME/.config/hypr/config}"
fi

MODE="${1:-}"

mkdir -p "$OUT_DIR" || exit 1

# round1 <base> <mult> -> "3.6" / "6" / "60" (1 decimal, no trailing .0).
round1() {
    awk -v b="$1" -v m="$2" 'BEGIN {
        v = b * m * 10;
        n = int(v + (v < 0 ? -0.5 : 0.5));
        if (n % 10 == 0) printf "%d", n / 10;
        else printf "%.1f", n / 10;
    }'
}

# lua_bool <0|1> -> true/false
lua_bool() { if [[ "$1" == "1" ]]; then printf "true"; else printf "false"; fi; }

# kdl_bool <0|1> -> true/false
kdl_bool() { if [[ "$1" == "1" ]]; then printf "true"; else printf "false"; fi; }

# Atomic write: stdin -> destination.
write_atomic() {
    local dest="$1" tmp
    tmp="$(mktemp "$OUT_DIR/.persist-appearance.XXXXXX")" || return 1
    cat > "$tmp" || { rm -f "$tmp"; return 1; }
    mv -f "$tmp" "$dest" || { rm -f "$tmp"; return 1; }
}

# luac -p gate: if it does not compile, drop it and fail.
validate_or_drop() {
    local file="$1"
    if ! luac -p "$file" >/dev/null 2>&1; then
        echo "persist-appearance: luac -p failed, dropping $file" >&2
        rm -f "$file"
        exit 1
    fi
}

reload_compositor() {
    if [[ "$NIRI" == "1" ]]; then
        [[ "${NIRI_NO_RELOAD:-0}" == "1" ]] && return 0
        niri msg action load-config-file >/dev/null 2>&1 || true
        if command -v notify-send >/dev/null 2>&1; then
            notify-send -t 1500 "niri" "Panel overrides applied (reload)" >/dev/null 2>&1 || true
        fi
    else
        [[ "${HYPR_NO_RELOAD:-0}" == "1" ]] && return 0
        hyprctl reload >/dev/null 2>&1 || true
        if command -v notify-send >/dev/null 2>&1; then
            notify-send -t 1500 "Hyprland" "Panel overrides applied (reload)" >/dev/null 2>&1 || true
        fi
    fi
}

# ─── animations ────────────────────────────────────────────────────────────
# niri_curve_node <hypr_curve> -> a complete KDL `curve` node. The bezier
# points mirror config/hypr/animations.lua:
#   smooth         0.25 0.1  0.25 1
#   overshot       0.13 0.99 0.29 1.15
#   easeInOutQuart 0.76 0     0.24 1
#   easeOutExpo    0.16 1     0.3  1   (niri has a named curve)
#   easeOutQuint   0.22 1     0.36 1
#   linear         0 0        1    1   (niri has a named curve)
niri_curve_node() {
    case "$1" in
        smooth)         printf 'curve "cubic-bezier" 0.25 0.1 0.25 1' ;;
        overshot)       printf 'curve "cubic-bezier" 0.13 0.99 0.29 1.15' ;;
        easeInOutQuart) printf 'curve "cubic-bezier" 0.76 0 0.24 1' ;;
        easeOutExpo)    printf 'curve "ease-out-expo"' ;;
        easeOutQuint)   printf 'curve "cubic-bezier" 0.22 1 0.36 1' ;;
        linear)         printf 'curve "linear"' ;;
        *)              printf 'curve "cubic-bezier" 0.13 0.99 0.29 1.15' ;;
    esac
}

run_animations_hypr() {
    local enabled="$1" speed="$2" wstyle="$3" wcurve="$4" sstyle="$5" wrap="$6" wopen="${7:-overshot}" wclose="${8:-expo}" out
    out="$OUT_DIR/user-animations.lua"
    {
        echo "-- Auto-generated by the Settings panel. Do not edit manually."
        echo "hl.config({ animations = { enabled = $(lua_bool "$enabled"), workspace_wraparound = $(lua_bool "$wrap") } })"
        echo ""
        echo "-- The 6 curves live in animations.lua (NOT redefined here): only the"
        echo "-- 12 animations are re-declared with the speed-scaled value."
        printf 'hl.animation({ leaf = "windowsIn",  enabled = true, speed = %s, bezier = "overshot", style = "popin 80%%" })\n' "$(round1 6 "$speed")"
        printf 'hl.animation({ leaf = "windowsOut", enabled = true, speed = %s, bezier = "easeOutExpo", style = "popin 80%%" })\n' "$(round1 5 "$speed")"
        printf 'hl.animation({ leaf = "windowsMove", enabled = true, speed = %s, bezier = "%s" })\n' "$(round1 5 "$speed")" "$wcurve"
        echo ""
        printf 'hl.animation({ leaf = "fadeIn",     enabled = true, speed = %s, bezier = "easeOutExpo" })\n' "$(round1 4 "$speed")"
        printf 'hl.animation({ leaf = "fadeOut",    enabled = true, speed = %s, bezier = "easeOutExpo" })\n' "$(round1 4 "$speed")"
        printf 'hl.animation({ leaf = "fadeSwitch", enabled = true, speed = %s, bezier = "easeOutExpo" })\n' "$(round1 4 "$speed")"
        printf 'hl.animation({ leaf = "fadeShadow", enabled = true, speed = %s, bezier = "easeOutExpo" })\n' "$(round1 4 "$speed")"
        printf 'hl.animation({ leaf = "fadeDim",    enabled = true, speed = %s, bezier = "easeOutExpo" })\n' "$(round1 4 "$speed")"
        echo ""
        printf 'hl.animation({ leaf = "border", enabled = true, speed = %s, bezier = "smooth" })\n' "$(round1 10 "$speed")"
        printf 'hl.animation({ leaf = "borderangle", enabled = true, speed = %s, bezier = "linear", style = "loop" })\n' "$(round1 100 "$speed")"
        echo ""
        printf 'hl.animation({ leaf = "workspacesIn",  enabled = true, speed = %s, bezier = "%s", style = "%s" })\n' "$(round1 6 "$speed")" "$wcurve" "$wstyle"
        printf 'hl.animation({ leaf = "workspacesOut", enabled = true, speed = %s, bezier = "%s", style = "%s" })\n' "$(round1 6 "$speed")" "$wcurve" "$wstyle"
        printf 'hl.animation({ leaf = "specialWorkspaceIn",  enabled = true, speed = %s, bezier = "%s", style = "%s" })\n' "$(round1 6 "$speed")" "$wcurve" "$sstyle"
        printf 'hl.animation({ leaf = "specialWorkspaceOut", enabled = true, speed = %s, bezier = "%s", style = "%s" })\n' "$(round1 6 "$speed")" "$wcurve" "$sstyle"
    } | write_atomic "$out" || exit 1
    validate_or_drop "$out"
    echo "user-animations.lua saved (enabled=$enabled speed=$speed style=$wstyle curve=$wcurve special=$sstyle wrap=$wrap)"
}

# niri_circle_shader <window-open|window-close> <speed>
# Custom circular reveal (open) / shrink (close) shader. The open shader is
# the expanding_circle example shipped with niri 26.04; the close shader uses
# the same mask with inverted progress. Custom shaders are version-sensitive.
niri_circle_shader() {
    local name="$1" speed="$2" fn progress
    if [[ "$name" == "window-open" ]]; then
        fn="open_color"
        progress="niri_clamped_progress"
    else
        fn="close_color"
        progress="1.0 - niri_clamped_progress"
    fi
    printf '    %s {\n' "$name"
    printf '        duration-ms %s\n' "$(round1 250 "$speed")"
    printf '        curve "linear"\n'
    printf '        custom-shader r"\n'
    printf '            vec4 %s(vec3 coords_geo, vec3 size_geo) {\n' "$fn"
    printf '                vec3 coords_tex = niri_geo_to_tex * coords_geo;\n'
    printf '                vec4 color = texture2D(niri_tex, coords_tex.st);\n'
    printf '                vec2 coords = (coords_geo.xy - vec2(0.5, 0.5)) * size_geo.xy * 2.0;\n'
    printf '                coords = coords / length(size_geo.xy);\n'
    printf '                float p = %s;\n' "$progress"
    printf '                if (p * p <= dot(coords, coords))\n'
    printf '                    color = vec4(0.0);\n'
    printf '                return color;\n'
    printf '            }\n'
    printf '        "\n'
    printf '    }\n'
}

# niri_window_block <window-open|window-close> <preset> <speed>
# Emits the niri animation node body. The speed multiplier scales easing
# durations; springs intentionally ignore it.
niri_window_block() {
    local name="$1" preset="$2" speed="$3"
    if [[ "$preset" == circle ]]; then
        niri_circle_shader "$name" "$speed"
        return 0
    fi
    printf '    %s {\n' "$name"
    case "$preset" in
        overshot) printf '        duration-ms %s\n        curve "cubic-bezier" 0.13 0.99 0.29 1.15\n' "$(round1 200 "$speed")" ;;
        expo)     printf '        duration-ms %s\n        curve "ease-out-expo"\n' "$(round1 150 "$speed")" ;;
        quad)     printf '        duration-ms %s\n        curve "ease-out-quad"\n' "$(round1 150 "$speed")" ;;
        cubic)    printf '        duration-ms %s\n        curve "ease-out-cubic"\n' "$(round1 180 "$speed")" ;;
        linear)   printf '        duration-ms %s\n        curve "linear"\n' "$(round1 120 "$speed")" ;;
        spring)   printf '        spring damping-ratio=1.0 stiffness=700 epsilon=0.0001\n' ;;
        bouncy)   printf '        spring damping-ratio=0.6 stiffness=700 epsilon=0.0001\n' ;;
        off)      printf '        off\n' ;;
        *)        printf '        duration-ms %s\n        curve "ease-out-expo"\n' "$(round1 150 "$speed")" ;;
    esac
    printf '    }\n'
}

run_animations_niri() {
    local enabled="$1" speed="$2" wstyle="$3" wcurve="$4" sstyle="$5" wrap="$6" wopen="${7:-overshot}" wclose="${8:-expo}" out
    out="$OUT_DIR/user-animations.kdl"
    if [[ "$enabled" != "1" ]]; then
        {
            echo "// Auto-generated by the Settings panel. Do not edit manually."
            echo "animations {"
            echo "    off"
            echo "}"
        } | write_atomic "$out" || exit 1
    else
        # Hyprland leaf names are remapped to niri animations:
        #   windowsIn/windowsOut -> window-open/window-close (selected preset)
        #   windowsMove          -> window-movement/window-resize (spring)
        #   workspaces           -> workspace-switch (duration + curve)
        #   borderangle, fade*   -> no niri equivalent, covered by global speed.
        # Workspace style, special-workspace style and wraparound have no niri
        # equivalent: they are parsed/validated but not emitted.
        {
            echo "// Auto-generated by the Settings panel. Do not edit manually."
            echo "// Hyprland leaf names remapped to niri animation nodes."
            echo "// workspace style=$wstyle special=$sstyle wrap=$wrap (Hyprland-only, ignored)."
            echo "animations {"
            niri_window_block "window-open" "$wopen" "$speed"
            niri_window_block "window-close" "$wclose" "$speed"
            printf '    workspace-switch {\n        duration-ms %s\n        %s\n    }\n' "$(round1 150 "$speed")" "$(niri_curve_node "$wcurve")"
            echo "    horizontal-view-movement {"
            echo "        spring damping-ratio=1.0 stiffness=800 epsilon=0.0001"
            echo "    }"
            echo "    window-movement {"
            echo "        spring damping-ratio=1.0 stiffness=800 epsilon=0.0001"
            echo "    }"
            echo "    window-resize {"
            echo "        spring damping-ratio=1.0 stiffness=800 epsilon=0.0001"
            echo "    }"
            echo "}"
        } | write_atomic "$out" || exit 1
    fi
    if command -v niri >/dev/null 2>&1 && ! niri validate -c "$out" >/dev/null 2>&1; then
        echo "persist-appearance: niri validate failed, dropping $out" >&2
        rm -f "$out"
        exit 1
    fi
    echo "user-animations.kdl saved (enabled=$enabled speed=$speed curve=$wcurve window-open=$wopen window-close=$wclose; style=$wstyle special=$sstyle wrap=$wrap ignored)"
}

# ─── input ─────────────────────────────────────────────────────────────────
run_input_hypr() {
    local sens="$1" profile="$2" tap="$3" natural="$4" dwt="$5" out
    out="$OUT_DIR/user-input.lua"
    {
        echo "-- Auto-generated by the Settings panel. Do not edit manually."
        echo "-- Pointer/touchpad only: kb_layout/kb_options/follow_mouse live in"
        echo "-- settings.lua and the partial hl.config merge keeps them."
        echo "hl.config({ input = {"
        echo "    sensitivity   = $sens,"
        echo "    accel_profile = \"$profile\","
        echo "    touchpad = {"
        echo "        natural_scroll       = $(lua_bool "$natural"),"
        echo "        disable_while_typing = $(lua_bool "$dwt"),"
        echo "        tap_to_click         = $(lua_bool "$tap"),"
        echo "    },"
        echo "} })"
    } | write_atomic "$out" || exit 1
    validate_or_drop "$out"
    echo "user-input.lua saved (sens=$sens profile=$profile tap=$tap natural=$natural dwt=$dwt)"
}

run_input_niri() {
    local sens="$1" profile="$2" tap="$3" natural="$4" dwt="$5" out
    out="$OUT_DIR/user-input.kdl"
    # niri splits pointer settings per device type and uses flags for booleans.
    {
        # `input {}` is a single-occurrence section: this generated fragment is
        # its sole owner, so it must carry the keyboard/focus settings that the
        # static module used to provide. The values mirror defaults/input.kdl.
        local lang opts
        lang="$(jq -r '.language // empty' "$HOME/.config/hypr/settings.json" 2>/dev/null || true)"
        opts="$(jq -r '.kbOptions // empty' "$HOME/.config/hypr/settings.json" 2>/dev/null || true)"
        [[ -n "$lang" ]] || lang="es"
        [[ -n "$opts" ]] || opts="grp:alt_shift_toggle"
        echo "// Auto-generated by the Settings panel. Do not edit manually."
        echo "input {"
        echo "    keyboard {"
        echo "        xkb {"
        echo "            layout \"$lang\""
        echo "            options \"$opts\""
        echo "        }"
        echo "    }"
        echo "    touchpad {"
        [[ "$tap" == "1" ]] && echo "        tap"
        [[ "$natural" == "1" ]] && echo "        natural-scroll"
        [[ "$dwt" == "1" ]] && echo "        dwt"
        echo "        accel-speed $sens"
        echo "        accel-profile \"$profile\""
        echo "    }"
        echo "    mouse {"
        echo "        accel-speed $sens"
        echo "        accel-profile \"$profile\""
        echo "    }"
        echo "    focus-follows-mouse max-scroll-amount=\"0%\""
        echo "}"
    } | write_atomic "$out" || exit 1
    if command -v niri >/dev/null 2>&1 && ! niri validate -c "$out" >/dev/null 2>&1; then
        echo "persist-appearance: niri validate failed, dropping $out" >&2
        rm -f "$out"
        exit 1
    fi
    echo "user-input.kdl saved (sens=$sens profile=$profile tap=$tap natural=$natural dwt=$dwt)"
}

# ─── dispatch ────────────────────────────────────────────────────────────────
case "$MODE" in
    animations)
        ENABLED="${2:-1}"
        SPEED="${3:-1.0}"
        WSTYLE="${4:-slide}"
        WCURVE="${5:-overshot}"
        SSTYLE="${6:-slidevert}"
        WRAP="${7:-0}"
        WOPEN="${8:-overshot}"
        WCLOSE="${9:-expo}"
        [[ "$ENABLED" == "1" ]] || ENABLED=0
        [[ "$SPEED" =~ ^[0-9]+([.][0-9]+)?$ ]] || SPEED=1.0
        case "$WSTYLE" in slide|slidefade|slidevert|slidefadevert|fade) ;; *) WSTYLE=slide ;; esac
        case "$SSTYLE" in slide|slidefade|slidevert|slidefadevert|fade) ;; *) SSTYLE=slidevert ;; esac
        case "$WCURVE" in smooth|overshot|easeInOutQuart|easeOutExpo|easeOutQuint|linear) ;; *) WCURVE=overshot ;; esac
        case "$WOPEN" in overshot|expo|quad|cubic|linear|spring|bouncy|circle|off) ;; *) WOPEN=overshot ;; esac
        case "$WCLOSE" in overshot|expo|quad|cubic|linear|spring|bouncy|circle|off) ;; *) WCLOSE=expo ;; esac
        [[ "$WRAP" == "1" ]] || WRAP=0
        if [[ "$NIRI" == "1" ]]; then
            run_animations_niri "$ENABLED" "$SPEED" "$WSTYLE" "$WCURVE" "$SSTYLE" "$WRAP" "$WOPEN" "$WCLOSE"
        else
            run_animations_hypr "$ENABLED" "$SPEED" "$WSTYLE" "$WCURVE" "$SSTYLE" "$WRAP"
        fi
        reload_compositor
        ;;
    input)
        SENS="${2:-0}"
        PROFILE="${3:-flat}"
        TAP="${4:-1}"
        NATURAL="${5:-1}"
        DWT="${6:-1}"
        [[ "$SENS" =~ ^-?[0-9]+([.][0-9]+)?$ ]] || SENS=0
        case "$PROFILE" in flat|adaptive) ;; *) PROFILE=flat ;; esac
        if [[ "$NIRI" == "1" ]]; then
            run_input_niri "$SENS" "$PROFILE" "$TAP" "$NATURAL" "$DWT"
        else
            run_input_hypr "$SENS" "$PROFILE" "$TAP" "$NATURAL" "$DWT"
        fi
        reload_compositor
        ;;
    *)
        echo "usage: persist-appearance.sh animations <0|1> <speed> <style> <curve> <special_style> <wrap> <window_open> <window_close> | persist-appearance.sh input <sensitivity> <profile> <tap> <natural> <dwt>" >&2
        exit 2
        ;;
esac
